import fs from 'node:fs';
import path from 'node:path';
import sharp from 'sharp';

/*
 * GY DATA exact branding
 *
 * The user's supplied 1024x1024 artwork is embedded below as
 * LOSSLESS WebP data.
 *
 * No separate image file is required.
 * The image is NOT redrawn.
 * The image is NOT cropped.
 * The image is NOT repositioned.
 * The image is NOT recolored.
 */

const projectRoot = process.cwd();

const androidMain = path.join(
  projectRoot,
  'android',
  'app',
  'src',
  'main',
);

if (!fs.existsSync(androidMain)) {
  throw new Error(
    `Android project not found: ${androidMain}`,
  );
}

/*
 * Exact user-supplied GY DATA image.
 *
 * It is lossless WebP, so when decoded it contains
 * the same pixels as the supplied PNG.
 */

const embeddedIconBase64 = [
  '',
  '',
  '',
  '',
].join('');

const exactIconBuffer = Buffer.from(
  embeddedIconBase64,
  'base64',
);

const metadata = await sharp(
  exactIconBuffer,
).metadata();

if (
  metadata.width !== 1024 ||
  metadata.height !== 1024
) {
  throw new Error(
    `Embedded GY DATA image is invalid: ${metadata.width}x${metadata.height}`,
  );
}

const resDir = path.join(
  androidMain,
  'res',
);

const drawableDir = path.join(
  resDir,
  'drawable',
);

const adaptiveDir = path.join(
  resDir,
  'mipmap-anydpi-v26',
);

const mipmapFolders = [
  'mipmap-mdpi',
  'mipmap-hdpi',
  'mipmap-xhdpi',
  'mipmap-xxhdpi',
  'mipmap-xxxhdpi',
];

const splashFolders = [
  'drawable-mdpi',
  'drawable-hdpi',
  'drawable-xhdpi',
  'drawable-xxhdpi',
  'drawable-xxxhdpi',
  'drawable-land-mdpi',
  'drawable-land-hdpi',
  'drawable-land-xhdpi',
  'drawable-land-xxhdpi',
  'drawable-land-xxxhdpi',
];

for (const directory of [
  drawableDir,
  adaptiveDir,
  ...mipmapFolders.map(
    (folder) => path.join(resDir, folder),
  ),
  ...splashFolders.map(
    (folder) => path.join(resDir, folder),
  ),
]) {
  fs.mkdirSync(
    directory,
    {
      recursive: true,
    },
  );
}

/*
 * Remove adaptive icons.
 *
 * This is intentional.
 * Adaptive icons can crop/mask the supplied artwork.
 */

for (const file of [
  'ic_launcher.xml',
  'ic_launcher_round.xml',
]) {
  const filePath = path.join(
    adaptiveDir,
    file,
  );

  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }
}

/*
 * Remove previous generated branding.
 */

for (const directory of [
  drawableDir,
  adaptiveDir,
  ...mipmapFolders.map(
    (folder) => path.join(resDir, folder),
  ),
  ...splashFolders.map(
    (folder) => path.join(resDir, folder),
  ),
]) {
  for (const file of [
    'ic_launcher.png',
    'ic_launcher_round.png',
    'ic_launcher_foreground.png',
    'ic_launcher_foreground.xml',
    'ic_launcher_background.png',
    'ic_launcher_background.xml',
    'splash.png',
    'splash.xml',
    'gy_data_splash.png',
    'gy_data_splash_background.xml',
  ]) {
    const filePath = path.join(
      directory,
      file,
    );

    if (fs.existsSync(filePath)) {
      fs.unlinkSync(filePath);
    }
  }
}

/*
 * IMPORTANT:
 *
 * We write the exact same image bytes to every launcher density.
 *
 * There is:
 * - no crop
 * - no resize
 * - no padding
 * - no reposition
 * - no recoloring
 * - no redesign
 */

for (const folder of mipmapFolders) {
  fs.writeFileSync(
    path.join(
      resDir,
      folder,
      'ic_launcher.png',
    ),
    exactIconBuffer,
  );

  fs.writeFileSync(
    path.join(
      resDir,
      folder,
      'ic_launcher_round.png',
    ),
    exactIconBuffer,
  );
}

/*
 * Exact native splash.
 */

fs.writeFileSync(
  path.join(
    drawableDir,
    'gy_data_splash.png',
  ),
  exactIconBuffer,
);

fs.writeFileSync(
  path.join(
    drawableDir,
    'splash.png',
  ),
  exactIconBuffer,
);

/*
 * Exact splash image for Android density folders.
 */

for (const folder of splashFolders) {
  fs.writeFileSync(
    path.join(
      resDir,
      folder,
      'splash.png',
    ),
    exactIconBuffer,
  );
}

/*
 * White background.
 */

fs.writeFileSync(
  path.join(
    drawableDir,
    'gy_data_splash_background.xml',
  ),
  `<?xml version="1.0" encoding="utf-8"?>
<shape xmlns:android="http://schemas.android.com/apk/res/android"
    android:shape="rectangle">
    <solid android:color="#FFFFFF" />
</shape>
`,
  'utf8',
);

/*
 * Make AndroidManifest use the direct PNG icon.
 */

const manifestPath = path.join(
  androidMain,
  'AndroidManifest.xml',
);

if (fs.existsSync(manifestPath)) {
  let manifest = fs.readFileSync(
    manifestPath,
    'utf8',
  );

  if (
    /android:icon="[^"]+"/.test(
      manifest,
    )
  ) {
    manifest = manifest.replace(
      /android:icon="[^"]+"/g,
      'android:icon="@mipmap/ic_launcher"',
    );
  } else {
    manifest = manifest.replace(
      /(<application\b)/,
      '$1\n        android:icon="@mipmap/ic_launcher"',
    );
  }

  if (
    /android:roundIcon="[^"]+"/.test(
      manifest,
    )
  ) {
    manifest = manifest.replace(
      /android:roundIcon="[^"]+"/g,
      'android:roundIcon="@mipmap/ic_launcher_round"',
    );
  } else {
    manifest = manifest.replace(
      /(<application\b[^>]*)(>)/,
      '$1\n        android:roundIcon="@mipmap/ic_launcher_round"$2',
    );
  }

  fs.writeFileSync(
    manifestPath,
    manifest,
    'utf8',
  );
}

/*
 * Verification.
 */

const requiredFiles = [
  path.join(
    resDir,
    'mipmap-mdpi',
    'ic_launcher.png',
  ),
  path.join(
    resDir,
    'mipmap-hdpi',
    'ic_launcher.png',
  ),
  path.join(
    resDir,
    'mipmap-xhdpi',
    'ic_launcher.png',
  ),
  path.join(
    resDir,
    'mipmap-xxhdpi',
    'ic_launcher.png',
  ),
  path.join(
    resDir,
    'mipmap-xxxhdpi',
    'ic_launcher.png',
  ),
  path.join(
    drawableDir,
    'gy_data_splash.png',
  ),
];

for (const filePath of requiredFiles) {
  if (!fs.existsSync(filePath)) {
    throw new Error(
      `GY DATA branding verification failed: ${filePath}`,
    );
  }
}

console.log('');
console.log('==============================================');
console.log('GY DATA BRANDING READY');
console.log('==============================================');
console.log('Exact supplied artwork embedded in source.');
console.log('No external image file required.');
console.log('No crop.');
console.log('No reposition.');
console.log('No adaptive-icon mask.');
console.log('Launcher icon generated.');
console.log('GY DATA splash generated.');
console.log('==============================================');
console.log('');
